// Apply technical indicators
const data = $input.all();
const symbol = data[0].json.params.symbol;
const indicators = data[0].json.params.indicators || ['sma', 'rsi'];

// Simulated analysis - replace with actual calculations
const analysis = {
  symbol: symbol,
  timestamp: new Date().toISOString(),
  indicators: {},
  signals: []
};

// Calculate indicators
if (indicators.includes('sma')) {
  analysis.indicators.sma = {
    sma20: 45000,
    sma50: 44500,
    sma200: 43000
  };
  if (analysis.indicators.sma.sma20 > analysis.indicators.sma.sma50) {
    analysis.signals.push({ type: 'bullish', indicator: 'SMA', strength: 'medium' });
  }
}

if (indicators.includes('rsi')) {
  analysis.indicators.rsi = {
    value: 65,
    period: 14
  };
  if (analysis.indicators.rsi.value > 70) {
    analysis.signals.push({ type: 'overbought', indicator: 'RSI', strength: 'high' });
  } else if (analysis.indicators.rsi.value < 30) {
    analysis.signals.push({ type: 'oversold', indicator: 'RSI', strength: 'high' });
  }
}

if (indicators.includes('macd')) {
  analysis.indicators.macd = {
    macd: 120,
    signal: 100,
    histogram: 20
  };
  if (analysis.indicators.macd.macd > analysis.indicators.macd.signal) {
    analysis.signals.push({ type: 'bullish', indicator: 'MACD', strength: 'medium' });
  }
}

// Overall recommendation
const bullishSignals = analysis.signals.filter(s => s.type === 'bullish').length;
const bearishSignals = analysis.signals.filter(s => s.type === 'bearish').length;

if (bullishSignals > bearishSignals) {
  analysis.recommendation = 'BUY';
  analysis.confidence = bullishSignals / analysis.signals.length;
} else if (bearishSignals > bullishSignals) {
  analysis.recommendation = 'SELL';
  analysis.confidence = bearishSignals / analysis.signals.length;
} else {
  analysis.recommendation = 'HOLD';
  analysis.confidence = 0.5;
}

return [{ json: analysis }];
